"""PokéLit original-host entry, independently reviewed 9 November 2026."""
from pathlib import Path
from site_analytics import write_html
ROOT = Path(__file__).resolve().parents[1]

def external(url, label):
    return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label} ↗<span class="sr-only"> (opens in a new tab)</span></a>'

def build():
    nav = '<a href="#play">Original game</a><a href="#start">Start here</a><a href="#devices">PC &amp; mobile</a><a href="#identity">Which game</a><a href="/#more-games">More games</a>'
    sections = [
        ('play', 'Open the original PokéLit game', f'''<p>Use <strong>pokelit.0d4y.cc</strong>, the address identified inside the original client. Select <strong>Press to start</strong> to reach the account screen, then choose Log in, Sign up or Sign in with Google. Have an account ready before planning a run. The original guide says an account is required to play and supplies cloud saves across devices.</p><p class="answer">{external('https://pokelit.0d4y.cc/', 'Open PokéLit on the original site')}</p><p>Destination is pokelit.0d4y.cc, opening in a new tab. Keep that tab for the game and this guide for the setup. The publisher prohibits embedding.</p><figure><a href="/assets/pokelit/title-original.png"><img src="/assets/pokelit/title-800.webp" srcset="/assets/pokelit/title-800.webp 800w, /assets/pokelit/title-1280.webp 1280w" sizes="(max-width:800px) calc(100vw - 40px),800px" width="1360" height="900" alt="PokéLit title screen with Meowth and the Press to start button"></a><figcaption>Original client title screen, captured 9 November 2026. This shows the entry screen before sign-in. SpriteCollab sprites, CC BY-NC 4.0; Pokémon © Nintendo/Creatures/GAME FREAK.</figcaption></figure><p>We checked the title-to-login transition. Account creation, cloud-save transfer and a complete run were not tested. Gameplay steps below follow the original project's guide and news, checked 9 November 2026; the capture has no displayed build number.</p>'''),
        ('start', 'A practical first-session route', f'''<ol><li><strong>Finish sign-in on the game site.</strong> Use the same account on each device if you want the project's documented cloud-save path. If you use a name and password, the account notice offers Gmail linking for recovery.</li><li><strong>Choose a partner, then begin a run.</strong> Movement and positioning are your active tasks. Moves fire automatically, so repeatedly tapping enemies is not the basic attack loop.</li><li><strong>Collect experience and read the level-up cards.</strong> Choose a new move, a move upgrade or a partner boost. Your run has up to four moves. For a first session, track those slots before replacing something you meant to upgrade.</li><li><strong>Move out of filling ground markers.</strong> Those circles and lines telegraph attacks. Make room to dodge before collecting a pickup in that area.</li><li><strong>Review permanent upgrades between runs.</strong> Coins can strengthen a favorite partner. Use an early session to learn movement before treating an unverified tier list as a reason to replace that partner.</li></ol><p>This route combines the entry screen with the {external('https://pokelit.0d4y.cc/guide/', 'original gameplay guide')}. It is setup guidance rather than a tested optimal build.</p>'''),
        ('devices', 'Choose the controls for your device', f'''<div class="table-wrap" tabindex="0" role="region" aria-label="Device controls, horizontally scrollable"><table><thead><tr><th>Device</th><th>Start with</th><th>Before a longer session</th></tr></thead><tbody><tr><td>Computer</td><td>WASD or arrow keys to move; Esc to pause</td><td>Keep the game tab focused and check movement before engaging a crowd.</td></tr><tr><td>Phone or tablet</td><td>Landscape orientation; drag to move; top-right pause control</td><td>Open Settings → Controls → Place the buttons to position attacks, pause and joystick where you can reach them.</td></tr><tr><td>Another device</td><td>Open the same original address and sign in to the same account</td><td>The project documents cloud saves. We have not verified transfer or conflict recovery.</td></tr></tbody></table></div><p>The original guide documents browser play and an optional Add to Home Screen install. Starting in the browser lets you check the game and account before choosing an installation route. Mobile button placement and a fixed joystick are described in the project's {external('https://pokelit.0d4y.cc/news/', '14 October news')}. We have not tested a physical phone or controller.</p>'''),
        ('identity', 'Separate similar names before using a guide', '''<p><strong>PokéLit / pokelit game / pokelit survivor</strong> refer here to the game at pokelit.0d4y.cc. Its own credits say it is based on PokéSurvivor by JPTER78. Shared ancestry does not establish shared accounts, identical versions or interchangeable progression instructions.</p><p><a href="/poke-survivor/">PokéSurvivor</a> has its own section on this site. <a href="/pokebonk/">PokeBonk</a> is another separate game. Open the matching game first, then use that game's guides. Pokémon Survivors and Pokelike searches can lead to other projects, so check the address and title before applying advice.</p><p>Pokelit AA and Acebeam Pokelit are flashlight names. Pokelit.com describes a Pokémon card collection service. Neither is the browser survival game covered here. “Pokelite” alone is ambiguous and does not establish a download destination.</p>'''),
        ('next', 'After you reach the menu', f'''<p>For move requirements, open the original guide's Moves section. For partner availability, follow its Pokédex. For playing with friends, the original guide documents up to four players, adding friends by nickname and inviting them to a room. Treat that as the project's documented mode, rather than a verified multiplayer test by this site.</p><p>If you were looking for another survivors game, use <a href="/#more-games">More games</a> to choose the matching game and its own entry guide. For corrections to this page, contact <a href="mailto:qsyhxw@gmail.com">qsyhxw@gmail.com</a>.</p>''')
    ]
    title = 'PokéLit Game: Original Site & PC/Mobile Start Guide'
    desc = 'Open the original PokéLit browser game, check its account requirement, learn PC and mobile controls, and distinguish it from similarly named games.'
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="https://megabonk.org/pokelit/"><meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="https://megabonk.org/pokelit/"><meta property="og:image" content="https://megabonk.org/assets/pokelit/title-1280.webp"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/vampire-survivors/site.css"><script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script></head><body class="guide-layout vs-guide"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="/"><span>Megabonk.org<small>Independent games &amp; guides</small></span></a><nav class="desktop-nav" aria-label="PokéLit navigation">{nav}</nav><details class="mobile-nav"><summary>Menu</summary><nav class="mobile-links" aria-label="PokéLit mobile navigation">{nav}</nav></details></div></header><main id="main" class="wrap"><header class="article-head"><p>POKÉLIT · BROWSER SURVIVAL</p><h1>PokéLit game &amp; starting guide</h1><div class="answer"><p>Play PokéLit at <strong>pokelit.0d4y.cc</strong> on PC or mobile. Start with the original site's account screen, then use automatic attacks while you steer your partner through the hordes.</p>{external('https://pokelit.0d4y.cc/', 'Open original PokéLit game')}</div><p class="byline">Megabonk.org editors · Checked 9 November 2026 · Independent fan-game guide</p></header><nav class="toc" aria-label="On this page">{''.join(f'<a href="#{key}">{heading}</a>' for key,heading,_ in sections)}</nav><div class="article-layout"><article class="prose">{''.join(f'<section id="{key}"><h2>{heading}</h2>{body}</section>' for key,heading,body in sections)}</article></div></main><footer class="footer"><div class="wrap footer-grid"><div><strong>Independent player guides</strong><p>Not affiliated with PokéLit, Nintendo, Creatures, GAME FREAK or The Pokémon Company.</p><a href="/#more-games">More games →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy">Privacy</a></nav></div></footer></body></html>'''
    target = ROOT / 'pokelit/index.html'
    target.parent.mkdir(exist_ok=True)
    write_html(target, html, encoding='utf8')
    target = ROOT / 'index.html'
    write_html(target, target.read_text(encoding='utf8'), encoding='utf8')

if __name__ == '__main__':
    build()
